<?php
require_once __DIR__ . '/../includes/auth.php';
require_once __DIR__ . '/../includes/helpers.php';
Auth::requireAdmin();
$db = Database::getInstance();

if ($_SERVER['REQUEST_METHOD'] === 'POST' && Auth::verifyCSRFToken(postParam('csrf_token'))) {
    $action = postParam('action');
    $enrollmentId = postParam('enrollment_id', null, FILTER_VALIDATE_INT);
    if ($action === 'approve_enrollment' && $enrollmentId) approveEnrollment($enrollmentId, Auth::getCurrentUserId());
    if ($action === 'approve_completion' && $enrollmentId) approveAdminCompletion($enrollmentId);
    if ($action === 'assign_trainer' && $enrollmentId) assignTrainer($enrollmentId, postParam('trainer_id', null, FILTER_VALIDATE_INT));
}
$stats = [
    'users' => $db->getValue('SELECT COUNT(*) FROM users'),
    'students' => $db->getValue("SELECT COUNT(*) FROM users WHERE role = 'student'"),
    'trainers' => $db->getValue("SELECT COUNT(*) FROM users WHERE role = 'trainer'"),
    'courses' => $db->getValue("SELECT COUNT(*) FROM courses WHERE status = 'published'"),
    'enrollments' => $db->getValue('SELECT COUNT(*) FROM enrollments'),
    'pending' => $db->getValue("SELECT COUNT(*) FROM enrollments WHERE status = 'pending'"),
    'completed' => $db->getValue("SELECT COUNT(*) FROM enrollments WHERE status = 'completed'"),
    'messages' => $db->getValue("SELECT COUNT(*) FROM contact_messages WHERE status = 'new'"),
    'revenue' => (float) $db->getValue("SELECT COALESCE(SUM(amount), 0) FROM payments WHERE status = 'paid'")
];
$enrollments = $db->getAll("SELECT e.id, e.status, e.progress, e.student_completed_at, e.trainer_approved_at, c.title, u.name AS student_name, e.trainer_id FROM enrollments e JOIN courses c ON c.id=e.course_id JOIN users u ON u.id=e.user_id ORDER BY e.updated_at DESC");
$trainers = $db->getAll("SELECT id, name FROM users WHERE role = 'trainer' AND status = 'active' ORDER BY name");
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Admin Dashboard | ICTECH</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.0/dist/css/bootstrap.min.css" rel="stylesheet"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css"><link rel="stylesheet" href="../assets/css/style.css?v=20260919"></head><body class="admin-shell"><div class="admin-app"><aside class="admin-sidebar"><div class="admin-sidebar-inner"><div class="sidebar-brand"><img src="../assets/images/ictech-logo-transparent.png" alt="ICTECH Solutions"></div><div class="admin-user-box"><p class="name"><?php echo h(Auth::getCurrentUser()['name'] ?? 'Administrator'); ?></p><p class="email"><?php echo h(Auth::getCurrentUser()['email'] ?? ''); ?></p></div><nav><?php $page = basename($_SERVER['PHP_SELF']); ?><a href="index.php" class="<?php echo $page === 'index.php' ? 'active' : ''; ?>"><i class="fas fa-tachometer-alt"></i> Dashboard</a><a href="users.php" class="<?php echo $page === 'users.php' ? 'active' : ''; ?>"><i class="fas fa-users"></i> Users</a><a href="enrollments.php" class="<?php echo $page === 'enrollments.php' ? 'active' : ''; ?>"><i class="fas fa-clipboard-list"></i> Enrollments</a><a href="courses.php" class="<?php echo $page === 'courses.php' ? 'active' : ''; ?>"><i class="fas fa-book-open"></i> Courses</a><a href="categories.php" class="<?php echo $page === 'categories.php' ? 'active' : ''; ?>"><i class="fas fa-tags"></i> Categories</a><a href="payments.php" class="<?php echo $page === 'payments.php' ? 'active' : ''; ?>"><i class="fas fa-credit-card"></i> Payments</a><a href="reports.php" class="<?php echo $page === 'reports.php' ? 'active' : ''; ?>"><i class="fas fa-chart-bar"></i> Reports</a><a href="testimonials.php" class="<?php echo $page === 'testimonials.php' ? 'active' : ''; ?>"><i class="fas fa-comments"></i> Testimonials</a><a href="partners.php" class="<?php echo $page === 'partners.php' ? 'active' : ''; ?>"><i class="fas fa-handshake"></i> Partners</a><a href="contact-messages.php" class="<?php echo $page === 'contact-messages.php' ? 'active' : ''; ?>"><i class="fas fa-envelope"></i> Messages</a><a href="settings.php" class="<?php echo $page === 'settings.php' ? 'active' : ''; ?>"><i class="fas fa-sliders-h"></i> Settings</a></nav><div class="sidebar-footer"><a href="../logout.php"><i class="fas fa-sign-out-alt"></i> Logout</a></div></div></aside><div class="admin-content"><header class="admin-topbar"><div class="admin-topbar-inner"><div class="brand-mark"><i class="fas fa-shield-alt"></i> Admin Console</div><div class="d-flex align-items-center gap-2"><div class="admin-user-chip"><i class="fas fa-user-circle"></i> <?php echo h(Auth::getCurrentUser()['name'] ?? 'Admin'); ?></div><a href="../logout.php" class="btn btn-sm btn-outline-primary"><i class="fas fa-sign-out-alt"></i> Logout</a></div></div></header><div class="admin-content-body"><main class="container-fluid px-0"><header class="admin-page-header d-flex flex-wrap justify-content-between align-items-center gap-3"><div><p class="eyebrow mb-2">ICTECH ADMIN CONSOLE</p><h1 class="mb-2">Operations Dashboard</h1><p class="text-muted mb-0">Manage learning delivery, content, and platform performance.</p></div><div class="d-flex gap-2 flex-wrap"><a href="courses.php" class="btn btn-primary">Manage Courses</a><a href="categories.php" class="btn btn-outline-primary">Categories</a><a href="payments.php" class="btn btn-outline-primary">Payments</a><a href="reports.php" class="btn btn-outline-primary">Reports</a><a href="settings.php#admin-access" class="btn btn-outline-primary">Admin Access</a><a href="create-trainer.php" class="btn btn-outline-primary">Create Trainer</a><a href="../logout.php" class="btn btn-outline-secondary">Logout</a></div></header><section class="row g-3 mb-5"><?php foreach ([['users','Total Users','fa-users','primary'],['students','Students','fa-user-graduate','info'],['trainers','Trainers','fa-chalkboard-user','warning'],['courses','Published Courses','fa-book-open','success'],['pending','Pending Enrollments','fa-hourglass-half','danger'],['completed','Completed Courses','fa-certificate','secondary'],['messages','New Messages','fa-envelope','dark']] as $stat): ?><div class="col-6 col-md-4 col-xl"><div class="card admin-stat-card h-100"><div class="card-body"><i class="fas <?php echo $stat[2]; ?> text-<?php echo $stat[3]; ?> mb-2"></i><div class="h3 mb-1"><?php echo (int) $stats[$stat[0]]; ?></div><small class="text-muted"><?php echo $stat[1]; ?></small></div></div></div><?php endforeach; ?><div class="col-12"><div class="card h-100"><div class="card-body"><div class="text-muted small mb-1">Total paid revenue</div><div class="h3 mb-0"><?php echo formatCurrency((float) $stats['revenue']); ?></div></div></div></div></div></section><section class="mb-4"><div class="card"><div class="card-body"><div class="d-flex flex-wrap gap-2"><?php foreach (['users.php','enrollments.php','payments.php','reports.php','testimonials.php','partners.php','contact-messages.php','settings.php'] as $page): ?><a href="<?php echo $page; ?>" class="btn btn-sm btn-outline-primary"><?php echo str_replace('-', ' ', pathinfo($page, PATHINFO_FILENAME)); ?></a><?php endforeach; ?></div></div></div></section><section class="card"><div class="card-body"><div class="d-flex justify-content-between align-items-center mb-3"><div><h2 class="h4 mb-1">Enrollment Workflow</h2><p class="text-muted mb-0">Approve requests, assign trainers, and authorize verified completion.</p></div><span class="badge text-bg-primary"><?php echo (int) $stats['enrollments']; ?> total</span></div><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Student</th><th>Course</th><th>Status</th><th>Trainer</th><th>Actions</th></tr></thead><tbody><?php foreach ($enrollments as $item): ?><tr><td><?php echo h($item['student_name']); ?></td><td><?php echo h($item['title']); ?></td><td><span class="badge text-bg-<?php echo $item['status'] === 'completed' ? 'success' : ($item['status'] === 'active' ? 'primary' : 'warning'); ?>"><?php echo h($item['status']); ?></span> <?php echo (int) $item['progress']; ?>%</td><td><?php echo $item['trainer_id'] ? 'Assigned' : 'Unassigned'; ?></td><td><form method="post" class="d-flex gap-2 flex-wrap"><input type="hidden" name="csrf_token" value="<?php echo h(Auth::generateCSRFToken()); ?>"><input type="hidden" name="enrollment_id" value="<?php echo (int) $item['id']; ?>"><select name="trainer_id" class="form-select form-select-sm"><option value="">Assign trainer</option><?php foreach ($trainers as $trainer): ?><option value="<?php echo (int) $trainer['id']; ?>"><?php echo h($trainer['name']); ?></option><?php endforeach; ?></select><button name="action" value="assign_trainer" class="btn btn-sm btn-outline-primary">Assign</button><?php if ($item['status'] === 'pending'): ?><button name="action" value="approve_enrollment" class="btn btn-sm btn-primary">Approve</button><?php endif; ?><?php if ($item['trainer_approved_at']): ?><button name="action" value="approve_completion" class="btn btn-sm btn-success">Approve Completion</button><?php endif; ?></form></td></tr><?php endforeach; ?><?php if (!$enrollments): ?><tr><td colspan="5" class="text-center text-muted py-4">No enrollment activity yet.</td></tr><?php endif; ?></tbody></table></div></div></section></main></div></div></div></body></html>
